from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from .models import EnterpriseKnowledgeArticle

@api_view(['GET'])
@permission_classes([IsAuthenticated])
def get_article_locale_draft(request, article_id, lang_code):
    # Enforce department scoping on the article lookup
    try:
        article = EnterpriseKnowledgeArticle.objects.get(pk=article_id, department=request.user.department)
    except EnterpriseKnowledgeArticle.DoesNotExist:
        return Response({'detail': 'Article not found'}, status=status.HTTP_404_NOT_FOUND)

    try:
        translation = article.get_translation(lang_code)
    except Exception:
        return Response({'detail': 'Translation not found'}, status=status.HTTP_404_NOT_FOUND)

    return Response({
        'article_id': article.id,
        'language': lang_code,
        'internal_translator_notes': translation.reviewer_notes,
        'confidential_draft_body': translation.draft_body
    })
